package cn.local.tomorrow;
import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public final class StateStore {
 public static synchronized JSONObject load(Context c)throws Exception {File f=new File(c.getFilesDir(),"state.json");if(!f.exists())return null;try(FileInputStream in=new FileInputStream(f)){return new JSONObject(new String(read(in,8000000),StandardCharsets.UTF_8));}}
 public static synchronized long save(Context c,JSONObject state,long expected)throws Exception {JSONObject old=load(c);long revision=old==null?0:old.optLong("_revision",0);if(expected>=0&&expected!=revision)throw new Exception("课表已在后台更新，请稍后重试");state.put("_revision",revision+1);File tmp=new File(c.getFilesDir(),"state.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(state.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!tmp.renameTo(new File(c.getFilesDir(),"state.json")))throw new IOException("课表保存失败");ClassReminders.onStateChanged(c);return revision+1;}
 public static byte[] read(InputStream in,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>limit)throw new IOException("文件过大");}return out.toByteArray();}
 public static void log(Context c,String text){try{File dir=c.getExternalFilesDir(null);if(dir==null)dir=c.getFilesDir();try(FileOutputStream out=new FileOutputStream(new File(dir,"applog.txt"),true)){String line=new java.text.SimpleDateFormat("MM-dd HH:mm:ss",java.util.Locale.US).format(new java.util.Date())+" "+text+"\n";out.write(line.getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
 public static void configure(WebView v){v.getSettings().setJavaScriptEnabled(true);v.getSettings().setDomStorageEnabled(true);v.getSettings().setAllowFileAccess(false);v.getSettings().setAllowContentAccess(false);v.getSettings().setSaveFormData(false);v.getSettings().setCacheMode(WebSettings.LOAD_NO_CACHE);}
 public static WebViewClient localAssets(Context c){return new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("https://app.local/");}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!r.getUrl().toString().startsWith("https://app.local/"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));String p=r.getUrl().getPath();if(p.contains(".."))return null;String mime=p.endsWith(".html")?"text/html":p.endsWith(".json")?"application/json":"application/javascript";try{return new WebResourceResponse(mime,"UTF-8",c.getAssets().open(p.substring(1)));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}};}
 static String owner=null;public static synchronized boolean acquire(String name){if(owner!=null)return false;owner=name;return true;}public static synchronized void release(String name){if(name.equals(owner))owner=null;}
}
